export const getDefaultImg = (): string => {
  const defualtImg = 'data:image/png;base64,'
  return defualtImg
}

export const debounce = (fn: () => unknown, delay: number): unknown => {
  let debounceTimer: NodeJS.Timeout | null
  return (...args: any) => {
    if (debounceTimer) {
      clearTimeout(debounceTimer)
    }
    debounceTimer = setTimeout(() => {
      fn.apply(this, args)
    }, delay)
  }
}
export interface TreeNode {
  id?: string;
  children?: TreeNode[];
}
export function getAllIds (node: TreeNode | null, acc: string[] = []): string[] {
  if (!node) return acc;

  if (node.id) {
    acc.push(node.id);
  }

  const children = node.children;
  if (children) {
    for (const child of children) {
      getAllIds(child, acc);
    }
  }

  return acc;
}

// 将分钟数转换为天、小时、分钟格式
export const formatDuration = (minutes: number): string => {
  if (!minutes && minutes !== 0) return '--'

  const days = Math.floor(minutes / (24 * 60))
  const hours = Math.floor((minutes % (24 * 60)) / 60)
  const mins = Math.floor(minutes % 60)

  const parts = []
  if (days > 0) parts.push(`${days}天`)
  if (hours > 0) parts.push(`${hours}小时`)
  if (mins > 0) parts.push(`${mins}分钟`)

  return parts.length > 0 ? parts.join('') : '0分钟'
}
